// @generated by scripts/generate-node-json.mjs from each class's `json`
// schema. Run `pnpm run generate-node-json` to regenerate; do not edit.

// Keys are emitted in the order the schema-driven walk writes them, so the two
// produce byte-identical JSON. That order is the schema's, not alphabetical.
/* eslint-disable sort-keys-fix/sort-keys-fix */

import type {LexicalNode} from './LexicalNode';
import type {CompactDefaultTest} from './LexicalUtils';
import type {ElementNode} from './nodes/LexicalElementNode';
import type {LineBreakNode} from './nodes/LexicalLineBreakNode';
import type {ParagraphNode} from './nodes/LexicalParagraphNode';
import type {TabNode} from './nodes/LexicalTabNode';
import type {TextNode} from './nodes/LexicalTextNode';

import {
  aliasTableOf,
  type ComposedSchemaFields,
  decodeTableOf,
  encodedDefaultOf,
  encodeTableOf,
} from './LexicalSchema';

/**
 * The generated implementations for one node class.
 *
 * Each is handed to the class it was generated from through that class's
 * `$config`, so nothing has to match code to class at runtime.
 *
 * @internal
 */
export interface GeneratedJSON {
  // Method syntax, so TypeScript checks the parameter bivariantly and a
  // function generated for one class is assignable here — the same reason
  // SerializationSchema.isEqual is declared this way. The alternative is to
  // widen the parameter to 'never', which no generated function actually
  // accepts and every call site then has to cast back.
  exportJSON(node: LexicalNode): {[key: string]: unknown};
  // `isCompactDefault` is the running class's own omission test, supplied by
  // the dispatch. Generated code states each property's comparison as source
  // where the default has a literal a value could be `===`; where it does not,
  // the comparison is this call, so the two forms omit the same properties
  // without the generated module holding a value import of anything. Most
  // exporters declare the parameter and never call it, and one generated
  // before it existed simply declares one parameter.
  exportCompactJSON?(
    node: LexicalNode,
    isCompactDefault: CompactDefaultTest,
  ): {[key: string]: unknown};
  // Returns the node the properties were applied to, which is the node passed
  // in unless a setter replaced it — the same value `$applyJSONSetters`
  // returns from the walk, for the same reason.
  updateFromJSON?(
    node: LexicalNode,
    json: {readonly [key: string]: unknown},
  ): LexicalNode;
  // Copies the fields this class's own `$config` declared, for the
  // `afterCloneFrom` synthesized from the same schema. The superclass's half is
  // that method's `super` call, so this covers one class's own fields and
  // nothing above it.
  afterCloneFrom?(node: LexicalNode, prevNode: LexicalNode): void;
}

/**
 * Builds the generated implementations for one class from that class's
 * composed schema, which the registration hands it: the lookup tables the
 * code reads are the schema's own objects, read from it here, so a generated
 * module holds no copy of a table and nothing about one is written into it
 * at build time.
 *
 * @internal
 */
export type GeneratedJSONFactory = (
  fields: ComposedSchemaFields,
) => GeneratedJSON;

// The JSON number grammar, anchored, matching numberValue: `Number()` alone
// reads '0x10' as 16 and '' as 0, and neither is a shape a JSON encoder
// produces. Emitted from the same source the codegen verified against, so the
// two cannot be different functions.
const JSON_NUMBER = /^-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?$/;

function num(v: unknown, d: number): number {
  if (typeof v === 'number') {
    return Number.isFinite(v) ? v : d;
  }
  if (typeof v !== 'string' || !JSON_NUMBER.test(v)) {
    return d;
  }
  const n = Number(v);
  return Number.isFinite(n) ? n : d;
}

function numC(
  v: unknown,
  d: number,
  min: number,
  max: number,
  integer: boolean,
): number {
  const n = num(v, d);
  return n >= min && n <= max && (!integer || Number.isInteger(n)) ? n : d;
}

/** ElementNode's generated implementations, for its `$config`. @internal */
export const GENERATED_ELEMENT: GeneratedJSONFactory = () => {
  /** Generated from ElementNode's serialization schema. Do not edit by hand. */
  function exportElementNode(node: ElementNode): {[key: string]: unknown} {
    const textFormat = node.__textFormat;
    const textStyle = node.__textStyle;
    const shouldSerializeTextStyles =
      (textFormat !== 0 || textStyle !== '') &&
      node.shouldSerializeTextStyles();
    return {
      children: [],
      direction: node.__dir,
      format: node.getFormatType(),
      indent: node.__indent,
      textFormat:
        textFormat !== 0 && shouldSerializeTextStyles ? textFormat : undefined,
      textStyle:
        textStyle !== '' && shouldSerializeTextStyles ? textStyle : undefined,
      type: node.__type,
      version: 1,
    };
  }

  /** Generated from ElementNode's serialization schema. Do not edit by hand. */
  function exportCompactElementNode(node: ElementNode): {
    [key: string]: unknown;
  } {
    const textFormat = node.__textFormat;
    const textStyle = node.__textStyle;
    const shouldSerializeTextStyles =
      (textFormat !== 0 || textStyle !== '') &&
      node.shouldSerializeTextStyles();
    const json: {[key: string]: unknown} = {type: node.__type, children: []};
    const direction = node.__dir;
    if (direction !== undefined && direction !== null) {
      json.direction = direction;
    }
    const format = node.getFormatType();
    if (format !== undefined && format !== '') {
      json.format = format;
    }
    const indent = node.__indent;
    if (indent !== undefined && indent !== 0) {
      json.indent = indent;
    }
    if (
      textFormat !== undefined &&
      textFormat !== 0 &&
      shouldSerializeTextStyles
    ) {
      json.textFormat = textFormat;
    }
    if (
      textStyle !== undefined &&
      textStyle !== '' &&
      shouldSerializeTextStyles
    ) {
      json.textStyle = textStyle;
    }
    return json;
  }

  /** Generated from ElementNode's serialization schema. Do not edit by hand. */
  function updateElementNode(
    node: ElementNode,
    json: {readonly [key: string]: unknown},
  ): ElementNode {
    let self = node;
    let n: unknown;
    let v: unknown;
    v = Object.prototype.hasOwnProperty.call(json, 'direction')
      ? json.direction
      : undefined;
    self.__dir = v === null || v === 'ltr' || v === 'rtl' ? v : null;
    v = Object.prototype.hasOwnProperty.call(json, 'format')
      ? json.format
      : undefined;
    n = self.setFormat(
      v === '' ||
        v === 'left' ||
        v === 'start' ||
        v === 'center' ||
        v === 'right' ||
        v === 'end' ||
        v === 'justify'
        ? v
        : '',
    );
    self = (n ?? self) as ElementNode;
    v = Object.prototype.hasOwnProperty.call(json, 'indent')
      ? json.indent
      : undefined;
    self.__indent = numC(v, 0, 0, Infinity, true);
    v = Object.prototype.hasOwnProperty.call(json, 'textFormat')
      ? json.textFormat
      : undefined;
    n = self.setTextFormat(num(v, 0));
    self = (n ?? self) as ElementNode;
    v = Object.prototype.hasOwnProperty.call(json, 'textStyle')
      ? json.textStyle
      : undefined;
    n = self.setTextStyle(typeof v === 'string' ? v : '');
    self = (n ?? self) as ElementNode;
    return self;
  }

  /** Generated from ElementNode's serialization schema. Do not edit by hand. */
  function afterCloneElementNode(
    node: ElementNode,
    prevNode: ElementNode,
  ): void {
    node.__dir = prevNode.__dir;
    node.__indent = prevNode.__indent;
    node.__textFormat = prevNode.__textFormat;
    node.__textStyle = prevNode.__textStyle;
  }

  return {
    exportJSON: exportElementNode,
    exportCompactJSON: exportCompactElementNode,
    updateFromJSON: updateElementNode,
    afterCloneFrom: afterCloneElementNode,
  };
};

/** TextNode's generated implementations, for its `$config`. @internal */
export const GENERATED_TEXT: GeneratedJSONFactory = fields => {
  const TEXT_MODE_DECODE = decodeTableOf(fields, 'mode') as {
    readonly [key: string]: 'normal' | 'segmented' | 'token';
  };

  const TEXT_DETAIL_ALIAS = aliasTableOf(fields, 'detail', 0) as {
    readonly [key: string]: 1 | 2;
  };

  const TEXT_FORMAT_ALIAS = aliasTableOf(fields, 'format', 0) as {
    readonly [key: string]:
      | 1
      | 2
      | 4
      | 8
      | 16
      | 32
      | 64
      | 128
      | 256
      | 512
      | 1024;
  };

  const TEXT_MODE_ENCODE = encodeTableOf(fields, 'mode') as {
    readonly [key: string]: 0 | 1 | 2;
  };

  const TEXT_MODE_ENCODE_DEFAULT = encodedDefaultOf(fields, 'mode') as
    | 0
    | 1
    | 2;

  /** Generated from TextNode's serialization schema. Do not edit by hand. */
  function exportTextNode(node: TextNode): {[key: string]: unknown} {
    return {
      detail: node.__detail,
      format: node.__format,
      mode: TEXT_MODE_DECODE[node.__mode],
      style: node.__style,
      text: node.__text,
      type: node.__type,
      version: 1,
    };
  }

  /** Generated from TextNode's serialization schema. Do not edit by hand. */
  function exportCompactTextNode(node: TextNode): {[key: string]: unknown} {
    const json: {[key: string]: unknown} = {type: node.__type};
    const detail = node.__detail;
    if (detail !== undefined && detail !== 0) {
      json.detail = detail;
    }
    const format = node.__format;
    if (format !== undefined && format !== 0) {
      json.format = format;
    }
    const mode = TEXT_MODE_DECODE[node.__mode];
    if (mode !== undefined && mode !== 'normal') {
      json.mode = mode;
    }
    const style = node.__style;
    if (style !== undefined && style !== '') {
      json.style = style;
    }
    const text = node.__text;
    if (text !== undefined && text !== '') {
      json.text = text;
    }
    return json;
  }

  /** Generated from TextNode's serialization schema. Do not edit by hand. */
  function updateTextNode(
    node: TextNode,
    json: {readonly [key: string]: unknown},
  ): TextNode {
    let v: unknown;
    v = Object.prototype.hasOwnProperty.call(json, 'detail')
      ? json.detail
      : undefined;
    node.__detail =
      typeof v === 'string' && v in TEXT_DETAIL_ALIAS
        ? TEXT_DETAIL_ALIAS[v]
        : num(v, 0);
    v = Object.prototype.hasOwnProperty.call(json, 'format')
      ? json.format
      : undefined;
    node.__format =
      typeof v === 'string' && v in TEXT_FORMAT_ALIAS
        ? TEXT_FORMAT_ALIAS[v]
        : num(v, 0);
    v = Object.prototype.hasOwnProperty.call(json, 'mode')
      ? json.mode
      : undefined;
    v = v === 'normal' || v === 'token' || v === 'segmented' ? v : 'normal';
    node.__mode =
      (v as string) in TEXT_MODE_ENCODE
        ? TEXT_MODE_ENCODE[v as string]
        : TEXT_MODE_ENCODE_DEFAULT;
    v = Object.prototype.hasOwnProperty.call(json, 'style')
      ? json.style
      : undefined;
    node.__style = typeof v === 'string' ? v : '';
    v = Object.prototype.hasOwnProperty.call(json, 'text')
      ? json.text
      : undefined;
    node.__text = typeof v === 'string' ? v : '';
    return node;
  }

  /** Generated from TextNode's serialization schema. Do not edit by hand. */
  function afterCloneTextNode(node: TextNode, prevNode: TextNode): void {
    node.__detail = prevNode.__detail;
    node.__format = prevNode.__format;
    node.__mode = prevNode.__mode;
    node.__style = prevNode.__style;
    node.__text = prevNode.__text;
  }

  return {
    exportJSON: exportTextNode,
    exportCompactJSON: exportCompactTextNode,
    updateFromJSON: updateTextNode,
    afterCloneFrom: afterCloneTextNode,
  };
};

